[2026-11-19] rc:4626820422 inline on src/test/fuzz/torcontrol.cpp by frankomosh (contributor) (edited 2026-11-19):
In SAFECOOKIE authentication, the controller should only send its `AUTHENTICATE` proof after verifying Tor's `SERVERHASH` (`torcontrol.cpp:639`). Currently, flipping that check either way still passes this target as well as other tests I have looked at.

`FakeTor` already knows when it has sent a correct server hash, so it could record the corresponding expected client hash and assert that every `AUTHENTICATE <hash>` matches one of those recorded hashes.

Patch if useful

```diff
@@ -29,6 +29,7 @@
 #include <cstdint>
 #include <deque>
 #include <memory>
+#include <set>
 #include <string>
 #include <string_view>
 #include <vector>
@@ -73,6 +74,9 @@ struct FakeTor {
     //! Verbs of the commands not yet answered on this connection, oldest first. Other operations can
     //! also complete replies, so this may drift from the controller's queue; that's still valid input.
     std::deque<std::string> unanswered;
+    //! Client hashes for server nonces we answered with a correct SERVERHASH. Mutable, as the reply
+    //! generators only get a const FakeTor.
+    mutable std::set<std::string> proven_client_hashes;

     void NewConnection()
     {
@@ -110,6 +114,10 @@ struct FakeTor {
             assert(cmd.find_first_of("\r\n") == std::string_view::npos);
             assert(std::ranges::any_of(VERBS, [&](std::string_view verb) { return cmd.starts_with(verb); }));
             unanswered.emplace_back(cmd.substr(0, cmd.find(' ')));
+            // SAFECOOKIE: the controller may only send its proof to a server that proved it knows the cookie.
+            if (cmd.starts_with("AUTHENTICATE ") && !cmd.starts_with("AUTHENTICATE \"")) {
+                assert(proven_client_hashes.contains(std::string{cmd.substr(std::string_view{"AUTHENTICATE "}.size())}));
+            }
             if (cmd.starts_with("AUTHCHALLENGE SAFECOOKIE ")) {
                 client_nonce = ParseHex(cmd.substr(std::string_view{"AUTHCHALLENGE SAFECOOKIE "}.size()));
             }
@@ -176,9 +184,11 @@ std::string ConsumeSocksLine(FuzzedDataProvider& provider)
 std::string ConsumeAuthChallengeLine(FuzzedDataProvider& provider, const FakeTor& tor)
 {
     const auto server_nonce{ConsumeFixedLengthByteVector(provider, 32)};
-    const auto server_hash{provider.ConsumeBool() ?
+    const bool correct{provider.ConsumeBool()};
+    const auto server_hash{correct ?
                                SafeCookieHash("Tor safe cookie authentication server-to-controller hash", tor.client_nonce, server_nonce) :
                                ConsumeFixedLengthByteVector(provider, 32)};
+    if (correct) tor.proven_client_hashes.insert(HexStr(SafeCookieHash("Tor safe cookie authentication controller-to-server hash", tor.client_nonce, server_nonce)));
     return "AUTHCHALLENGE SERVERHASH=" + HexStr(server_hash) + " SERVERNONCE=" + HexStr(server_nonce);
 }
```
